def maxJumps(arr, d):
    n = len(arr)
    dp = [0] * n

    def solve(i):
        if dp[i] != 0:
            return dp[i]

        max_reachable = 1

        # Jump to the right
        for j in range(i + 1, min(i + d + 1, n)):
            valid_jump = True
            for k in range(i + 1, j):
                if arr[i] <= arr[k]:
                    valid_jump = False
                    break
            if valid_jump and arr[i] > arr[j]:
                max_reachable = max(max_reachable, 1 + solve(j))

        # Jump to the left
        for j in range(i - 1, max(i - d - 1, -1), -1):
            valid_jump = True
            for k in range(j + 1, i):
                if arr[i] <= arr[k]:
                    valid_jump = False
                    break
            if valid_jump and arr[i] > arr[j]:
                max_reachable = max(max_reachable, 1 + solve(j))

        dp[i] = max_reachable
        return dp[i]

    max_indices = 0
    for i in range(n):
        max_indices = max(max_indices, solve(i))

    return max_indices

