class MyCalendarTwo:

    def __init__(self):
        self.calendar = []
        self.overlaps = []

    def book(self, start: int, end: int) -> bool:
        for s, e in self.overlaps:
            if start < e and end > s:
                return False
        for s, e in self.calendar:
            if start < e and end > s:
                self.overlaps.append((max(start, s), min(end, e)))
        self.calendar.append((start, end))
        return True

def test_my_calendar_two():
    cal = MyCalendarTwo()

    test_cases = [
        ((10, 20), True),
        ((50, 60), True),
        ((10, 40), True),
        ((5, 15), False),
        ((5, 10), True),
        ((25, 55), True),
    ]

    results = []
    for event, expected in test_cases:
        result = cal.book(*event)
        results.append(result == expected)
        print(result == expected)

    print(f"{sum(results)}/{len(results)}")

if __name__ == "__main__":
    test_my_calendar_two()

def hit_bricks(grid, hits):
    m = len(grid)
    n = len(grid[0])

    def is_valid(row, col):
        return 0 <= row < m and 0 <= col < n

    def dfs(row, col, visited):
        if not is_valid(row, col) or grid[row][col] != 1 or (row, col) in visited:
            return 0

        visited.add((row, col))

        count = 1
        count += dfs(row + 1, col, visited)
        count += dfs(row - 1, col, visited)
        count += dfs(row, col + 1, visited)
        count += dfs(row, col - 1, visited)

        return count

    # Mark hits as -1 temporarily
    for row, col in hits:
        if grid[row][col] == 1:
            grid[row][col] = -1

    # Make stable bricks as 1
    for col in range(n):
        if grid[0][col] == 1:
            dfs(0, col, set())

    result = []
    for row, col in reversed(hits):
        if grid[row][col] == -1:
            grid[row][col] = 1

            # Check if the brick is connected to the top
            is_connected = row == 0

            # Check if the brick is adjacent to a stable brick
            if not is_connected:
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    new_row, new_col = row + dr, col + dc
                    if is_valid(new_row, new_col) and grid[new_row][new_col] == 1:
                        is_connected = True
                        break

            if is_connected:
                before = dfs(0, 0, set()) if grid[0][0] == 1 else 0
                visited = set()
                dfs(row, col, visited)
                after = dfs(0, 0, set()) if grid[0][0] == 1 else 0

                fallen = after - before - 1
                result.append(max(0, fallen))
            else:
                result.append(0)
        else:
            result.append(0)

    return result[::-1]

def test_hit_bricks():
    test_cases = [
        {
            "grid": [[1,0,0,0],[1,1,1,0]],
            "hits": [[1,0]],
            "expected": [2]
        },
        {
            "grid": [[1,0,0,0],[1,1,0,0]],
            "hits": [[1,1],[1,0]],
            "expected": [0,0]
        },
        {
            "grid": [[1,1,1],[0,1,0],[0,0,0]],
            "hits": [[0,2],[2,0],[0,0]],
            "expected": [0,1,0]
        },
        {
            "grid": [[1,1,1],[1,0,1],[1,1,1]],
            "hits": [[1,1],[0,1]],
            "expected": [1,0]
        }
    ]

    num_correct = 0
    total_tests = len(test_cases)

    for i, test_case in enumerate(test_cases):
        grid = [row[:] for row in test_case["grid"]]  # Create a deep copy
        hits = test_case["hits"]
        expected = test_case["expected"]

        result = hit_bricks(grid, hits)

        if result == expected:
            print(f"Test {i+1}: True")
            num_correct += 1
        else:
            print(f"Test {i+1}: False")
            print(f"  Input: grid={test_case['grid']}, hits={hits}")
            print(f"  Expected: {expected}")
            print(f"  Got: {result}")

    print(f"\n{num_correct}/{total_tests} correct")

if __name__ == "__main__":
    test_hit_bricks()

import heapq

def getSkyline(buildings):
    """
    :type buildings: List[List[int]]
    :rtype: List[List[int]]
    """
    events = []
    for l, r, h in buildings:
        events.append((l, -h, r))  # Start of building, negative height
        events.append((r, 0, 0))  # End of building, height 0

    events.sort()

    skyline = []
    live = [(0, float('inf'))]  # (height, end)
    heapq.heapify(live)

    for x, neg_h, r in events:
        while live[0][1] <= x:
            heapq.heappop(live)

        if neg_h != 0:
            heapq.heappush(live, (neg_h, r))

        if not skyline or -skyline[-1][1] != live[0][0]:
            skyline.append((x, -live[0][0]))

    return skyline

def test_getSkyline():
    test_cases = [
        {
            "input": [[2,9,10],[3,7,15],[5,12,12],[15,20,10],[19,24,8]],
            "expected": [[2,10],[3,15],[7,12],[12,0],[15,10],[20,8],[24,0]]
        },
        {
            "input": [[0,2,3],[2,5,3]],
            "expected": [[0,3],[5,0]]
        },
        {
            "input": [[1,2,1],[1,2,2],[1,2,3]],
            "expected": [[1,3],[2,0]]
        },
        {
            "input": [[0,5,7],[5,10,7],[5,10,12],[10,15,7],[15,20,7],[0,5,12],[20,25,7]],
            "expected": [[0,12],[5,12],[10,7],[15,7],[20,7],[25,0]]
        },
        {
            "input": [],
            "expected": []
        }
    ]

    num_correct = 0
    total_tests = len(test_cases)

    for i, test_case in enumerate(test_cases):
        buildings = test_case["input"]
        expected = test_case["expected"]
        actual = getSkyline(buildings)

        if actual == expected:
            print(f"Test {i+1}: True")
            num_correct += 1
        else:
            print(f"Test {i+1}: False")
            print(f"  Input: {buildings}")
            print(f"  Expected: {expected}")
            print(f"  Actual: {actual}")

    print(f"\nCorrect: {num_correct}/{total_tests}")

