        ([0, 0, 0], 3),
        ([1, 2, 87, 87, 87, 2, 1], 13)
    ]

    correct_count = 0
    total_count = len(test_cases)

    for ratings, expected in test_cases:
        result = candy(ratings)
        if result == expected:
            print("True")
            correct_count += 1
        else:
            print("False")

    print(f"{correct_count}/{total_count}")

