def ip_to_int(ip):
    parts = ip.split('.')
    result = 0
    for i in range(4):
        result = (result << 8) + int(parts[i])
    return result

def int_to_ip(num):
    parts = []
    for i in range(4):
        parts.insert(0, str(num & 255))
        num >>= 8
    return '.'.join(parts)

def ip_to_cidr(ip, n):
    start = ip_to_int(ip)
    result = []
    while n > 0:
        mask = 32
        while mask > 0:
            masked_start = start & ((1 << mask) - 1) ^ start
            if masked_start != 0 or (n < (1 << (32 - mask))):
                mask -= 1
            else:
                break
        result.append(int_to_ip(start) + '/' + str(mask))
        start += (1 << (32 - mask))
        n -= (1 << (32 - mask))
    return result

