def longest_line(matrix):
    """
    Finds the longest line of consecutive ones in a 01 matrix.

    Args:
        matrix: A list of lists representing the 01 matrix.

    Returns:
        The length of the longest line of consecutive ones.
    """
    if not matrix or not matrix[0]:
        return 0

    rows = len(matrix)
    cols = len(matrix[0])
    max_len = 0

    # Horizontal
    for i in range(rows):
        count = 0
        for j in range(cols):
            if matrix[i][j] == 1:
                count += 1
                max_len = max(max_len, count)
            else:
                count = 0

    # Vertical
    for j in range(cols):
        count = 0
        for i in range(rows):
            if matrix[i][j] == 1:
                count += 1
                max_len = max(max_len, count)
            else:
                count = 0

    # Diagonal (top-left to bottom-right)
    for i in range(rows):
        count = 0
        r, c = i, 0
        while r < rows and c < cols:
            if matrix[r][c] == 1:
                count += 1
                max_len = max(max_len, count)
            else:
                count = 0
            r += 1
            c += 1

    for j in range(1, cols):
        count = 0
        r, c = 0, j
        while r < rows and c < cols:
            if matrix[r][c] == 1:
                count += 1
                max_len = max(max_len, count)
            else:
                count = 0
            r += 1
            c += 1

    # Anti-diagonal (top-right to bottom-left)
    for i in range(rows):
        count = 0
        r, c = i, cols - 1
        while r < rows and c >= 0:
            if matrix[r][c] == 1:
                count += 1
                max_len = max(max_len, count)
            else:
                count = 0
            r += 1
            c -= 1

    for j in range(cols - 2, -1, -1):
        count = 0
        r, c = 0, j
        while r < rows and c >= 0:
            if matrix[r][c] == 1:
                count += 1
                max_len = max(max_len, count)
            else:
                count = 0
            r += 1
            c -= 1

    return max_len


