            "expected": [[0,3],[5,0]]
        },
        {
            "input": [[1,2,1],[1,2,2],[1,2,3]],
            "expected": [[1,3],[2,0]]
        },
        {
            "input": [[1,5,3],[1,5,3]],
            "expected": [[1,3],[5,0]]
