def solve():
    def subarraySum(nums, n, left, right):
        sums = []
        for i in range(n):
            curr_sum = 0
            for j in range(i, n):
                curr_sum += nums[j]
                sums.append(curr_sum)

        sums.sort()

        total_sum = 0
        for i in range(left - 1, right):
            total_sum = (total_sum + sums[i]) % (10**9 + 7)

        return total_sum

