import heapq

def mincostToHireWorkers(quality, wage, K):
    N = len(quality)
    workers = []
    for i in range(N):
        workers.append((wage[i] / quality[i], quality[i]))

    workers.sort()

    total_quality = 0
    heap = []
    ans = float('inf')

    for ratio, q in workers:
        heapq.heappush(heap, -q)
        total_quality += q

        if len(heap) > K:
            total_quality += heapq.heappop(heap)

        if len(heap) == K:
            ans = min(ans, ratio * total_quality)

    return ans

