class WordFilter:
    def __init__(self, words):
        self.words = words

    def f(self, prefix, suffix):
        indices = []
        for i, word in enumerate(self.words):
            if word.startswith(prefix) and word.endswith(suffix):
                indices.append(i)
        if not indices:
            return -1
        else:
            return max(indices)

