class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def isValidBST(root: TreeNode) -> bool:
    def isValidBSTHelper(node, min_val, max_val):
        if not node:
            return True

        if node.val <= min_val or node.val >= max_val:
            return False

        return (isValidBSTHelper(node.left, min_val, node.val) and
                isValidBSTHelper(node.right, node.val, max_val))

    return isValidBSTHelper(root, float('-inf'), float('inf'))

def test_isValidBST():
    test_cases = [
        ([2,1,3], True),
        ([5,1,4,None,None,3,6], False),
        ([1,1], False),
        ([1,None,2,2],False),
        ([0,None,-1], False),
        ([5,4,6,None,None,3,7], False),
        ([3,1,5,0,2,4,6], True),
        ([2,2,2], False)
    ]

    def build_tree(arr, index=0):
        if index >= len(arr) or arr[index] is None:
            return None

        node = TreeNode(arr[index])
        node.left = build_tree(arr, 2 * index + 1)
        node.right = build_tree(arr, 2 * index + 2)
        return node

    num_correct = 0
    total_tests = len(test_cases)

    for arr, expected_output in test_cases:
        root = build_tree(arr)
        actual_output = isValidBST(root)

        if actual_output == expected_output:
            print("True")
            num_correct += 1
        else:
            print("False")

    print(f"{num_correct}/{total_tests}")

if __name__ == "__main__":
    test_isValidBST()

def matrix_rank_transform(matrix):
    """
    Given an m x n matrix, return a new matrix answer where answer[row][col] is the rank of matrix[row][col].
    """
    m, n = len(matrix), len(matrix[0])
    ranks = [0] * (m + n)  # Separate ranks for rows and columns
    answer = [[0] * n for _ in range(m)]

    # Sort elements with their row and col indices
    elements = []
    for r in range(m):
        for c in range(n):
            elements.append((matrix[r][c], r, c))
    elements.sort()

    i = 0
    while i < len(elements):
        j = i
        group = []
        while j < len(elements) and elements[i][0] == elements[j][0]:
            val, r, c = elements[j]
            group.append((r, c))
            j += 1

        # Find maximum ranks from row and column
        row_max_ranks = [ranks[r] for r in range(m)]
        col_max_ranks = [ranks[m + c] for c in range(n)]

        for r, c in group:
            max_rank = max(row_max_ranks[r], col_max_ranks[c])
            answer[r][c] = max_rank + 1

        # Update ranks for row and column
        for r, c in group:
            ranks[r] = answer[r][c]
            ranks[m + c] = answer[r][c]

        i = j

    return answer

