def reorder_logs(logs):
    letter_logs = []
    digit_logs = []
    for log in logs:
        words = log.split()
        if words[1].isdigit():
            digit_logs.append(log)
        else:
            letter_logs.append(log)

    letter_logs.sort(key=lambda x: (x.split(maxsplit=1)[1], x.split()[0]))
    return letter_logs + digit_logs

