def solve():
    def count_remaining_nodes(nodes, parent, value):
        adj = [[] for _ in range(nodes)]
        for i in range(1, nodes):
            adj[parent[i]].append(i)

        subtree_sums = [0] * nodes
        remaining_nodes = set(range(nodes))

        def calculate_subtree_sum(node):
            subtree_sums[node] = value[node]
            for child in adj[node]:
                subtree_sums[node] += calculate_subtree_sum(child)
            return subtree_sums[node]

        calculate_subtree_sum(0)

        def remove_zero_sum_subtrees(node):
            if subtree_sums[node] == 0:
                if node in remaining_nodes:
                    remaining_nodes.remove(node)
                for child in adj[node]:
                    remove_zero_sum_subtrees(child)

                return

            for child in adj[node]:
                remove_zero_sum_subtrees(child)


        remove_zero_sum_subtrees(0)

        return len(remaining_nodes)

    test_cases = [
        (7, [-1, 0, 0, 1, 2, 2, 2], [1, -2, 4, 0, -2, -1, -1], 2),
        (7, [-1, 0, 0, 1, 2, 2, 2], [1, -2, 4, 0, -2, -1, -2], 6),
        (5, [-1, 0, 1, 0, 0], [-672, 441, 18, 728, 378], 5),
        (5, [-1, 0, 0, 1, 1], [-686, -842, 616, -739, -746], 5),
        (4, [-1, 0, 1, 0], [0,1,2,0], 2),
        (4, [-1, 0, 0, 1], [0, 1, 2, 0], 2),
        (4, [-1,0,1,0], [0,1,-1,0], 1)
    ]

    num_correct = 0
    for i, (nodes, parent, value, expected) in enumerate(test_cases):
        result = count_remaining_nodes(nodes, parent, value)
        if result == expected:
            print(f"True")
            num_correct += 1
        else:
            print(f"False")
    print(f"{num_correct}/{len(test_cases)}")

solve()

def num_distinct_islands2(grid):
    """
    Counts the number of distinct islands in a grid, considering rotations and reflections.

    Args:
        grid: A 2D array of 0's and 1's representing the grid.

    Returns:
        The number of distinct islands.
    """

    def dfs(i, j, path):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == 0:
            return
        grid[i][j] = 0
        path.append((i - start_i, j - start_j))
        dfs(i + 1, j, path)
        dfs(i - 1, j, path)
        dfs(i, j + 1, path)
        dfs(i, j - 1, path)

    def normalize(path):
        normalized_path = []
        for i, j in path:
            normalized_path.append((i, j))
        return tuple(sorted(normalized_path))

    def rotate(island):
        new_island = []
        for x, y in island:
            new_island.append((-y, x))
        return normalize(new_island)

    def reflect(island):
        new_island = []
        for x, y in island:
            new_island.append((x, -y))
        return normalize(new_island)

    def all_transforms(island):
        transforms = set()
        for _ in range(4):
            island = rotate(island)
            transforms.add(island)
            transforms.add(reflect(island))
        return transforms

    islands = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                path = []
                start_i = i
                start_j = j
                dfs(i, j, path)
                normalized_island = normalize(path)

                transforms = all_transforms(normalized_island)

                islands.add(min(transforms))

    return len(islands)


